// === besar.js ===
console.log("besar.js dijalankan");
export function dipakai() {
  return "fitur utama";
}
export function jarang() {
  return "fitur jarang";
}
// === main.js ===
import { dipakai } from "./besar.js";
console.log(dipakai());

