globalThis.mataUang = "Rp";
console.log("format.js mengubah variabel global");
export function harga(n) {
  return globalThis.mataUang + n.toLocaleString("id-ID");
}
export function persen(n) {
  return n * 100 + "%";
}
// === main.js ===
import { harga } from "./format.js";
console.log(harga(25000));

