cards.solution:
// === format.js ===
export function harga(n) {
  return "Rp" + n.toLocaleString("id-ID");
}
export function persen(n) {
  return n * 100 + "%";
}
// === main.js ===
import { harga } from "./format.js";
console.log(harga(25000));
